CREATE TABLE IF NOT EXISTS messages (id BIGSERIAL PRIMARY KEY, sender_id UUID REFERENCES profiles(id) ON DELETE CASCADE, receiver_id UUID REFERENCES profiles(id) ON DELETE CASCADE, content TEXT NOT NULL, is_read BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_messages_sender_receiver ON messages(sender_id, receiver_id, created_at DESC); CREATE INDEX IF NOT EXISTS idx_messages_unread ON messages(receiver_id, is_read, created_at DESC); ALTER TABLE messages ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can view own messages" ON messages FOR SELECT USING (sender_id = auth.uid() OR receiver_id = auth.uid()); CREATE POLICY "Users can send messages" ON messages FOR INSERT WITH CHECK (sender_id = auth.uid()); CREATE POLICY "Users can update own received messages" ON messages FOR UPDATE USING (receiver_id = auth.uid()); 
